public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = computeDelimitedSize(message, schema, buffer);
    writeRawBytes(out, Bytes.getIntBytes(size), 0, 4);
    writeRawBytes(out, schema.toByteArray(message), 0, size);
    return size + 4;
}

void writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
  int size = schema.getSerializedSize(message);
  if (size == -1) {
    throw new RuntimeException("Size of message is unknown");
  }
  out.write(new byte[] {(byte)((size >>> 24) & 0xff), (byte)((size >>> 16) & 0xff), (byte)((size >>> 8) & 0xff), (byte)(size & 0xff)});
  schema.writeTo(out, message, LinkedBuffer.getBuffer(size, true));
  return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    pruneRecursive(message, buffer);
    out.write(1);
    int size = schema.getSize(message);
    out.write(size);
    schema.write(message, out, buffer);
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.getMessageSize(message);
    // Write the size of the message in the stream first
    out.writeInt(messageSize);
    buffer.writeRawBytes(out, messageSize);
    return messageSize + 4; // 4 is the size of the message length prefix
}

private static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int initialSize = buffer.getPosition();
    schema.writeDelimitedTo(out, message, buffer);
    return (buffer.getPosition() - initialSize);
}

