Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    if (actualTypeArguments.length != 1) {
        return null;
    }
    Type actualTypeArgument = actualTypeArguments[0];
    if (actualTypeArgument instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
        for (TypeVariable<?> typeParameter : typeParameters) {
            if (typeVariable.getName().equals(typeParameter.getName())) {
                actualTypeArgument = typeParameter.getBounds()[0];
                break;
            }
        }
    }
    if (actualTypeArgument instanceof Class) {
        return new Class<?>[]{(Class<?>) actualTypeArgument};
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    List<Type> typeArguments = new ArrayList<>();
    if (genericType instanceof ParameterizedType) {
        Type rawType = ((ParameterizedType) genericType).getRawType();
        if (!rawType.equals(targetType)) {
            return null;
        }
        Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
        for (Type actualTypeArgument : actualTypeArguments) {
            if (actualTypeArgument instanceof TypeVariable) {
                String typeVariableName = ((TypeVariable) actualTypeArgument).getName();
                TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
                for (TypeVariable<?> typeParameter : typeParameters) {
                    if (typeParameter.getName().equals(typeVariableName)) {
                        typeArguments.add(typeParameter.getBounds()[0]);
                        break;
                    }
                }
            } else {
                typeArguments.add(actualTypeArgument);
            }
        }
        return typeArguments.toArray(new Class<?>[0]);
    } else {
        return null;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
	if (genericType == null || targetType == null) {
		return null;
	}
	if (!(genericType instanceof ParameterizedType)) {
		return null;
	}
	ParameterizedType parameterizedType = (ParameterizedType) genericType;
	Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
	Class<?>[] resolvedArguments = new Class[actualTypeArguments.length];
	for (int i = 0; i < actualTypeArguments.length; i++) {
		Type actualTypeArgument = actualTypeArguments[i];
		if (actualTypeArgument instanceof TypeVariable) {
			TypeVariable typeVariable = (TypeVariable) actualTypeArgument;
			TypeVariableMap typeVariableMap = getTypeVariableMap(targetType);
			Class<?> resolvedType = typeVariableMap.get(typeVariable.getName());
			if (resolvedType == null) {
				return null;
			}
			resolvedArguments[i] = resolvedType;
		} else if (actualTypeArgument instanceof Class) {
			resolvedArguments[i] = (Class<?>) actualTypeArgument;
		}
	}
	return resolvedArguments;
}

private static TypeVariableMap getTypeVariableMap(Class<?> targetType) {
	Map<String, TypeVariable<?>> typeVariableMap = new HashMap<>();
	populateTypeVariableMap(targetType, typeVariableMap);
	return new TypeVariableMap(typeVariableMap);
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        if (typeArguments == null || typeArguments.length == 0) {
            return null;
        }
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
        if (typeParameters == null || typeParameters.length == 0) {
            return null;
        }
        Map<TypeVariable<?>, Type> typeMap = new HashMap<>();
        for (int i = 0; i < typeArguments.length; i++) {
            typeMap.put(typeParameters[i], typeArguments[i]);
        }
        return Arrays.stream(typeArguments).map(type -> resolveType(type, typeMap)).toArray(Class<?>[]::new);
    } else {
        return null;
    }
}

