    // Check if tableName is not null or empty
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }

    // Get the current mappings for the table from the input mappings
    Mappings currentMappings = mappings.get(tableName);

    // Check if current mappings is not null
    if (currentMappings == null) {
        throw new IllegalArgumentException("Current mappings cannot be null");
    }

    // Get the history mappings for the table from the input mappings
    Mappings historyMappings = mappings.getHistory(tableName);

    // Check if history mappings is not null
    if (historyMappings == null) {
        throw new IllegalArgumentException("History mappings cannot be null");
    }

    // Create a new Mappings object to store the differences
    Mappings differences = new Mappings();

    // Iterate over the current mappings and check if the fields exist in the history mappings
    for (Field currentField : currentMappings.getFields()) {
        if (!historyMappings.hasField(currentField.name())) {
            differences.putField(currentField);
        }
    }

    // Iterate over the history mappings and check if the fields exist in the current mappings
    for (Field historyField : historyMappings.getFields()) {
        if (!currentMappings.hasField(historyField.name())) {
            differences.putField(historyField);
        }
    }

    // Return the differences
    return differences;
}

