private List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || start >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("start must be between 0 and " + FETCH_DATA_DURATION);
    }
    if (end < start || end >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("end must be between start and " + FETCH_DATA_DURATION);
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    long currentEnd = Math.min(end, FETCH_DATA_DURATION);
    while (currentStart < currentEnd) {
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long timeRangeSize = TimeRange.FETCH_DATA_DURATION;
    while (start <= end) {
        TimeRange timeRange = new TimeRange(start, Math.min(start + timeRangeSize, end));
        timeRanges.add(timeRange);
        start = timeRange.getEndMillis();
    }
    return timeRanges;
}

List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        TimeRange timeRange = new TimeRange();
        timeRange.start = start;
        timeRange.end = Math.min(end, start + FETCH_DATA_DURATION);
        timeRanges.add(timeRange);
        start = timeRange.end + 1;
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
   // Split time ranges to ensure that the start time and end time are small than FETCH_DATA_DURATION
   List<TimeRange> timeRanges = new ArrayList<>();
   long duration = end - start;
   long currentStart = start;
   while (currentStart < end) {
      long currentEnd = currentStart + Math.min(FETCH_DATA_DURATION, duration);
      timeRanges.add(new TimeRange(currentStart, currentEnd));
      currentStart = currentEnd;
   }
   return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long diff = end - start;
    if (diff < FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long startOfRange = start;
        while (startOfRange < end) {
            long endOfRange = startOfRange + FETCH_DATA_DURATION;
            if (endOfRange > end) {
                endOfRange = end;
            }
            timeRanges.add(new TimeRange(startOfRange, endOfRange));
            startOfRange += FETCH_DATA_DURATION;
        }
    }
    return timeRanges;
}

