public static long compressTimeBucket ( long timeBucket, int dayStep ) {
    int day = ( int ) ( timeBucket / 1000000 );
    int month = ( int ) ( timeBucket % 1000000 / 100 );
    int year = ( int ) ( timeBucket % 1000000 / 100 / 10000 );

    int formattedDay = dayStep * ( ( day - 1 ) / dayStep + 1 );
    int formattedMonth = month;
    int formattedYear = year;

    if ( formattedDay > 100 ) {
        formattedMonth++;
        if ( formattedMonth > 12 ) {
            formattedMonth -= 12;
            formattedYear++;
        }
    }

    return ( long ) ( formattedYear * 10000 + formattedMonth * 100 + formattedDay );
}

private static long compressTimeBucket(long timeBucket, int dayStep) {
double remainder = timeBucket % dayStep;
timeBucket -= remainder;
return timeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);
    day += dayStep;
    if (day > 28) {
        day = day % 28;
        month += 1;
    }
    if (month > 11) {
        month = month % 12;
        year += 1;
    }
    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long newTimeBucket = timeBucket;
    if (dayStep == 11) {
        newTimeBucket = timeBucket / 10 - 12 * 10 + dayStep;
    } else if (dayStep == 12) {
        newTimeBucket = timeBucket / 10 - 11 * 10 + dayStep;
    } else if (dayStep == 13) {
        newTimeBucket = timeBucket / 10 - 10 * 10 + dayStep;
    } else if (dayStep == 14) {
        newTimeBucket = timeBucket / 10 - 9 * 10 + dayStep;
    } else if (dayStep == 15) {
        newTimeBucket = timeBucket / 10 - 8 * 10 + dayStep;
    }
    return newTimeBucket;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
        int size = 0;
        for (int i = index; i < index + len; i++) {
            char ch = str.charAt(i);
            if (ch <= 0x7F) {
                size++;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else if (ch <= 0xFFFF) {
                size += 3;
            } else if (ch <= 0x10FFFF) {
                size += 4;
            }
        }
        return size;
    }

