    int size = 0;
    for (int i = index; i < index + len; i++) {
        if (str.charAt(i) < 0x80) {
            size++;
        } else if (str.charAt(i) < 0x800) {
            size += 2;
        } else if (str.charAt(i) >= 0xd800 && str.charAt(i) < 0xdfff) {
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

