void writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) {
  final byte[] utf8Bytes = str.toString().getBytes(StandardCharsets.UTF_8);
  if (lb.length < utf8Bytes.length) {
    lb.expand(utf8Bytes.length - lb.length);
  }
  lb.writeInt(utf8Bytes.length, session.out);
  for (int i = 0; i < utf8Bytes.length; i++) {
    lb.writeByte(utf8Bytes[i], session.out);
  }
  lb.writeInt(0, session.out);
  return lb;
}

public static LinkedBuffer writeUTF8(String str, WriteSession session, LinkedBuffer lb) {
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c >= 0 && c <= 127) {
            lb.writeByte((byte) c);
        } else {
            lb.writeByte((byte) (0xc0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3f)));
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int length = str.length();
    byte[] bytes = new byte[length * 3 + 1];
    int idx = 0;
    for (int i = 0; i < length; i++) {
        char ch = str.charAt(i);
        if (ch < 128) {
            bytes[idx++] = (byte) ch;
        } else if (ch < 2048) {
            bytes[idx++] = (byte) ((ch >> 6) | 192);
            bytes[idx++] = (byte) ((ch & 63) | 128);
        } else {
            bytes[idx++] = (byte) ((ch >> 12) | 224);
            bytes[idx++] = (byte) (((ch >> 6) & 63) | 128);
            bytes[idx++] = (byte) ((ch & 63) | 128);
        }
    }
    LinkedBuffer ret = new LinkedBuffer(length * 3 + 1);
    ret.writeBytes(bytes, 0, bytes.length);
    return ret;
}

