void pop(String descriptor) {
   int numPointers = descriptor.length();
   for (int i = 0; i < numPointers; i++) {
      ASMStack frame = top();
      if (frame.getOpcode() == Opcodes.GETSTATIC || frame.getOpcode() == Opcodes.PUTSTATIC) {
         Object object = frame.getObject();
         if (object instanceof AbstractType) {
            frame.setObject((AbstractType) object);
            pop();
         }
      }
   }
}

private void pop(String descriptor) {
    int n = descriptor.startsWith("(") ? descriptor.replaceAll("\\(", "").length() : 1;
    for (int i = 0; i < n; i++) {
        frame.pop();
    }
}

private void pop(final String descriptor) {
if (descriptor.startsWith("L")) {
final Type t = Type.getObjectType(descriptor.substring(1));
// Pop as many slots as needed for the type (Note that slots are 128bits
// wide and array types are referenced by a single slot, so we need to
// scale the array length to the number of slots).
for (int i = 0; i < (t.getSort() == Type.ARRAY ? t.getDimensions() : 1); i++) {
stack.pop();
}
} else if (descriptor.startsWith("(")) {
// Pop method return value and arguments.
final List<Type> types = Type.getArgumentTypes(descriptor);
for (Type t : types) {
stack.pop();
}
} else {
// Primitive type.
stack.pop();
}
}

