public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("The desired capacity must not be negative: " + desiredCapacity);
    }

    if (desiredCapacity < 1000) {
        return (desiredCapacity < 11) ? 11 : (desiredCapacity < 191) ? 191 : (desiredCapacity < 383) ? 383 : desiredCapacity;
    } else {
        for (int i = desiredCapacity; ; i += 32) {
            for (int j = 1; j < 32; j++) {
                if (i * 11 / 10 <= prime * i) {
                    return prime;
                }
            }
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    // Find the closest prime number to the desired capacity
    for (int i = desiredCapacity + 1; i < (desiredCapacity * 1.1); i++) {
        if (isPrime(i)) {
            return i;
        }
    }
    return desiredCapacity;
}

