public static int nextPrime(int desiredCapacity) {
    int primeNumber;
    if (desiredCapacity >= 1000) {
        primeNumber = desiredCapacity % 2 == 0 ? desiredCapacity - 1 : desiredCapacity;
        for (int i = desiredCapacity + 2; i <= 2 * desiredCapacity; i++) {
            if (isPrime(i)) {
                primeNumber = i;
                break;
            }
        }
    } else {
        primeNumber = nextPrime(desiredCapacity * 2);
