}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i * i <= number; i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
	if (desiredCapacity < 0) {
		throw new IllegalArgumentException("Invalid desiredCapacity: " + desiredCapacity);
	}

	// Handle small values directly
	if (desiredCapacity < 10) {
		return 19;
	}

	int candidate = (int)Math.ceil(desiredCapacity / 0.7);

	while (!isPrime(candidate)) {
		candidate += 2;
	}

	return candidate;
}

private static boolean isPrime(int candidate) {
	if (candidate <= 3) {
		return candidate > 1;
	}

	int maxFactor = (int)Math.sqrt(candidate);
	for (int i = 2; i <= maxFactor; i++) {
		if (candidate % i == 0) {
			return false;
		}
	}

	return true;
}

