public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }
        StringBuffer buffer = new StringBuffer(str.length());
        // reader for the input string
        CharReader reader = new CharReader(str);
        while (!reader.atEnd) {
            switch (reader.nextChar) {
                case '\'':
                    if (reader.hasMore && reader.nextChar == '\'') {
                        buffer.append('\'');
                        break;
                    }
                case '\"':
                    if (reader.hasMore && reader.nextChar == '\"') {
                        buffer.append('\"');
                        break;
                    }
                case 'b':
                    if (reader.hasMore && reader.nextChar == 'b') {
                        buffer.append("\b");
                        break;
                    }
                case 'f':
                    if (reader.hasMore && reader.nextChar == 'f') {
                        buffer.append("\f");
                        break;
                    }
                case 'n':
                    if (reader.hasMore && reader.nextChar == 'n') {
                        buffer.append("\n");
                        break;
                    }
                case 'r':
                    if (reader.hasMore && reader.nextChar == 'r') {
                        buffer.append("\r");
                        break;
                    }
                case 't':
                    if (reader.hasMore && reader.nextChar == 't') {
                        buffer.append("\t");
                        break;
                    }
                case '\\':
                    if (reader.hasMore && reader.nextChar == 'v') {
                        buffer.append("\v");
                        break;
                    }
                default:
                    buffer.append(reader.nextChar);
                    break;
            }
        }
        return buffer.toString();
    }

