public static String unescapeJava(String str) {
  if (str == null) {
    return null;
  }
  StringBuilder sb = new StringBuilder();
  int len = str.length();
  for (int i = 0; i < len; i++) {
    char ch = str.charAt(i);
    if (ch == '\\') {
      char nextCh = str.charAt(i + 1);
      switch (nextCh) {
        case '\\':
          sb.append("\\");
          break;
        case 't':
          sb.append("\t");
          break;
        case 'n':
          sb.append("\n");
          break;
        case 'r':
          sb.append("\r");
          break;
        case 'f':
          sb.append("\f");
          break;
        case 's':
          sb.append(" ");
          break;
        default:
          if (nextCh > '0' && nextCh <= '7') {
            int value = (int) nextCh - 48;
            for (int j = 2; j > 0; j--) {
              i++;
              ch = str.charAt(i);
              if (ch < '0' || ch > '7') {
                break;
              }
              value = value * 8 + (int) ch - 48;
            }
            sb.append((char) value);
          } else {
            sb.append("\\");
            if (nextCh == 'u') {
              for (int j = 0; j < 4; j++) {
                i++;
                ch = str.charAt(i);
                if (ch == 'u') {
                  sb.append("u");
                } else {
                  sb.append(ch);
                }
              }
            }
          }
      }
    } else {
      sb.append(ch);
    }
  }
  return sb.toString();
}

