    if (len == 0) {
        return str;
    }

    StringBuffer buffer = new StringBuffer(len);
    boolean escape = false;
    boolean unicode = false;
    char ch;

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (escape) {
            if (c == 'u') {
                unicode = true;
                buffer.append(c);
            } else {
                buffer.append(ESCAPES.get(c));
                escape = false;
