public final MatchResult match(CharSequence uri) {
    if (this.getTemplatePrefix() != null && !uri.startsWith(this.getTemplatePrefix())) {
        return null;
    }

    if (this.getTemplateSuffix() != null && !uri.endsWith(this.getTemplateSuffix())) {
        return null;
    }

    String[] templateVariables = this.getTemplateVariables();
    String[] splitUri = uri.split("/");

    if (templateVariables.length != splitUri.length) {
        return null;
    }

    for (int i = 0; i < templateVariables.length; i++) {
        if (!templateVariables[i].equals(splitUri[i])) {
            return null;
        }
    }

    MatchResult result = new MatchResult();
    result.setTemplateVariables(templateVariables);
    result.setMatchingTemplate(this);
    return result;
}

