}

public byte readByte() throws IOException {
    // Check if the buffer needs to be refill
    if (buf.position() == buf.limit()) {
        refillBuf();
    }

    // Read a byte from the buffer
    byte b = buf.get();

    // Update the position
    buf.position(buf.position() + 1);

    // Return the byte
    return b;
}

private void refillBuf() throws IOException {
    // Check if the buffer is full
    if (buf.position() != 0) {
        // Create a new buffer with double the size
        ByteBuffer newBuf = ByteBuffer.allocate(buf.limit() * 2);

        // Copy the data from the current buffer to the new buffer
        newBuf.put(buf);

        // Make the new buffer the current buffer
        buf = newBuf;
    }

    // Read more data from the input stream into the current buffer
    in.read(buf);

    // Set the position and limit of the buffer
    buf.position(buf.position() - 1);
    buf.limit(buf.capacity());
}

