        return buffer.get();
    }
    return fillBufferAndReadByte();
}

private byte fillBufferAndReadByte() throws IOException {
    buffer.compact();
    int bytesRead = stream.read(buffer.array(), buffer.position(), buffer.remaining());
    if (bytesRead == -1) {
        throw new IOException("No more data available");
    }
    buffer.limit(buffer.position() + bytesRead);
    return buffer.get();
}

