private boolean unlink(ListNodeImpl<E> node) {
  // Check if the given node is not null
  if (node == null) {
    return false;
  }

  // Check if the given node is the head of the list
  if (head == node) {
    // Remove the head node from the list
    head = head.getNext();
    return true;
  }

  // Find the previous node of the given node
  ListNodeImpl<E> currentNode = head;
  while (currentNode.getNext() != node) {
    currentNode = currentNode.getNext();
  }

  // Remove the given node from the list
  currentNode.setNext(node.getNext());
  return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    boolean isRemoved = false;
    if (node != null) {
        if (node.getPrev() != null) {
            node.getPrev().setNext(node.getNext());
        }
        if (node.getNext() != null) {
            node.getNext().setPrev(node.getPrev());
        }
        if (head == node) {
            head = node.getNext();
        }
        if (tail == node) {
            tail = node.getPrev();
        }
        isRemoved = true;
    }
    return isRemoved;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNode<E> previous;
    if (node == head) {
        previous = head.previous();
        head = previous.next();
    } else {
        previous = node.previous();
        previous.next(node.next());
    }
    if (node == tail) {
        tail = previous;
    }
    node.previous(null).next(null);
    size--;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.getPrev();
    ListNodeImpl<E> next = node.getNext();
    if (prev == null) {
        // node is the first node
        if (next == null) {
            // only one node in the list
            this.head = null;
            this.tail = null;
        } else {
            // next node will be the new head
            this.head = next;
            next.setPrev(null);
        }
    } else {
        // node is not the first node
        if (next == null) {
            // only one node after this node
            this.tail = prev;
            prev.setNext(null);
        } else {
            // multiple nodes after this node
            prev.setNext(next);
            next.setPrev(prev);
        }
    }
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    if (head == tail) {
        head = tail = null;
    } else {
        if (node == head) {
            head = node.next;
        }
        if (node == tail) {
            tail = node.prev;
        }
        if (node.prev != null) {
            node.prev.next = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        }
    }
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

