public static final <V> void reverse(V[] arr, int from, int to) {
int i = from - 1;
int j = to;
while (i < j) {
i++;
j--;
V temp = arr[i];
arr[i] = arr[j];
arr[j] = temp;
}
}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Create a new array with the same type as the input array
    V[] newArr = (V[]) new Object[arr.length];
    // Iterate over the range of elements to be reversed
    for (int i = from; i <= to; i++) {
        // Get the element from the input array at the current index
        V element = arr[i];
        // Insert the current element into the new array at the end of the range
        newArr[to - (i - from)] = element;
    }
    // Replace the elements in the input array with the elements in the new array
    for (int i = from; i <= to; i++) {
        arr[i] = newArr[i];
    }
}

