    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayLit<>();
    for (E e :  getEdges(graph)) {
        List<Pair<Integer,Integer>> separatorList = new ArrayLit<>();
        for (E selectedEdge : getNeighborhood(e)) {
            if (selectedEdge != e) {
                separatorList.addAll(computeMinimalSeparators(selectedEdge));
            }
        }
        globalSeparatorList.add(new Pair<List<Pair<Integer,Integer>>,E>(separatorList, e));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    // Create an empty list to store the results
    List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();

    // Iterate over the edges of the graph
    for (E edge : graph.getEdges()) {
        // Create a list to store the separators for the current edge
        List<Pair<Integer,Integer>> separators = new ArrayList<>();

        // Iterate over the vertices in the neighborhood of the current edge
        for (V vertex : edge.getVertices()) {
            // Compute the minimal separators for the current vertex
            List<Pair<Integer,Integer>> minimalSeparators = computeMinimalSeparators(vertex);

            // Append the minimal separators to the list of separators for the current edge
            separators.addAll(minimalSeparators);
        }

        // Add the pair of separators and the current edge to the result list
        result.add(new Pair<>(separators, edge));
    }

    // Return the final result list
    return result;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer, Integer>> minimalSeparatorList = new ArrayList<>();
        for (Pair<Integer, Integer> endpoint : e.endpoints()) {
            minimalSeparatorList.addAll(computeMinimalSeparatorList(endpoint.left(), endpoint.right(), e));
        }
        globalSeparatorList.add(new Pair<>(minimalSeparatorList, e));
    }
    return globalSeparatorList;
}

private List<Pair<Integer, Integer>> computeMinimalSeparatorList(int v, int w, E e) {
    List<Pair<Integer, Integer>> minimalSeparatorList = new ArrayList<>();
    if (v == w) {
        return minimalSeparatorList;
    }
    for (E otherEdge : graph.getEdges()) {
        if (otherEdge != e && graph.hasEdge(v, w, otherEdge)) {
            minimalSeparatorList.add(new Pair<>(v, w));
            break;
        }
    }
    if (minimalSeparatorList.isEmpty()) {
        for (E otherEdge : graph.getEdges()) {
            if (otherEdge != e && graph.hasEdge(v, otherEdge) && graph.hasEdge(otherEdge, w)) {
                minimalSeparatorList.addAll(computeMinimalSeparatorList(v, otherEdge, e));
                minimalSeparatorList.addAll(computeMinimalSeparatorList(otherEdge, w, e));
                break;
            }
        }
    }
    return minimalSeparatorList;
}

public List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> list = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer,Integer>> minSepList = new ArrayList<>();
        for (E neighbor : graph.getNeighbors(e)) {
            List<Pair<Integer,Integer>> minSep = computeMinimalSeparator(e, neighbor);
            minSepList.addAll(minSep);
        }
        list.add(new Pair<>(minSepList, e));
    }
    return list;
}

