/**
 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    // Create a copy of the graph with only the specified vertices
    Graph<V,E> subgraph = graph.subgraph(vertices);

    // Iterate over the vertices of the subgraph and check if every two vertices are connected
    for (V vertex1 : subgraph.getVertices()) {
        for (V vertex2 : subgraph.getVertices()) {
            if (vertex1 != vertex2 && !subgraph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    // If no edges are missing, the subgraph is a clique
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check that the subgraph is complete by comparing it to every possible permutation of the vertices
    for (Permutation<V> p : Permutations.of(vertices)) {
        // Check that every vertex in the subgraph is adjacent to every other vertex
        for (V v1 : vertices) {
            for (V v2 : p.asSet()) {
                if (!graph.containsEdge(v1, v2)) {
                    return false;
                }
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if all pairwise vertex connections are present in the graph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.edgeExists(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
	 Set<V> visitedVertices = new HashSet<>();
	 LinkedList<V> verticesToVisit = new LinkedList<>();
	 verticesToVisit.addAll(vertices);

	 while (!verticesToVisit.isEmpty()) {
	     V v = verticesToVisit.removeFirst();
	     if(!visitedVertices.contains(v)){
	         visitedVertices.add(v);
	         verticesToVisit.addAll(graph.adjacentVertices(v));
	     }
	 }

	 return visitedVertices.size() == vertices.size() && verticesToVisit.isEmpty();
 }

