String buildContentRange() {

  // Calculate the actual content length
  long actualContentLength = content.length() - (offset + contentStartPosition); 

  // Calculate the length of the partial content
  long partialContentLength = actualContentLength;

  // If the partial content is >= 0, calculate the length of the partial content
  if (partialContentLength >= 0) {
    partialContentLength = length - offset;
  }

  // Calculate the Content-Range value
  String contentRange = "bytes #" + offset + "-" + actualContentLength + "/" + length;

  // If the partial content is > 0, include the Content-Range value with the partial content length
  if (partialContentLength > 0) {
    contentRange = "bytes #" + offset + "-" + actualContentLength + "/" + length;
  }

  // If the partial content is <= 0, include the Content-Range value with the length
  if (partialContentLength <= 0) {
    contentRange = "bytes *" + length;
  }

  // Return the Content-Range value
  return contentRange; 

}

List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    FileInputStream in = new FileInputStream(file);
    BufferedReader reader = new BufferedReader(new InputStreamReader(in));
    String line = reader.readLine();
    while (line != null) {
        // parse the line and create a ThreadSnapshot object
        ThreadSnapshot snapshot = new ThreadSnapshot();
        // set the timestamp based on the specified time ranges
        snapshot.setTimestamp(getTimestamp(line, timeRanges));
        // set other properties of the ThreadSnapshot object
        snapshot.setId(line.split(" ")[0]);
        snapshot.setName(line.split(" ")[1]);
        snapshot.setStart(line.split(" ")[2]);
        snapshot.setEnd(line.split(" ")[3]);
        snapshots.add(snapshot);
        line = reader.readLine();
    }
    return snapshots;
}

private static long getTimestamp(String line, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        long rangeStart = Long.parseLong(range.getStart());
        long rangeEnd = Long.parseLong(range.getEnd());
        long lineTime = Long.parseLong(line.split(" ")[0]);
        if (rangeStart <= lineTime && rangeEnd >= lineTime) {
            return lineTime;
        }
    }
    return 0;
}

public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

      List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
      Reader reader = new FileReader(file);
      BufferedReader bufReader = new BufferedReader(reader);
      long prevSnapshotTime = 0L;
      long snapshotTime = 0L;
      String line = bufReader.readLine();
      while (line != null) {
            String[] lineArr = line.split(",");
            snapshotTime = Long.parseLong(lineArr[0]);
            if (snapshotTime >= timeRanges.get(0).getStartTime() && snapshotTime <= timeRanges.get(0).getEndTime()) {
                  threadSnapshots.add(new ThreadSnapshot(snapshotTime, prevSnapshotTime, lineArr[1]));
            }
            prevSnapshotTime = snapshotTime;
            line = bufReader.readLine();
      }
      return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = null;
        ThreadSnapshot currentSnapshot = null;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("# gnu time") || line.startsWith("# ---")) {
                continue;
            }
            if (line.startsWith("0")) {
                currentSnapshot = new ThreadSnapshot();
                threadSnapshots.add(currentSnapshot);
                currentSnapshot.addEntry(new ThreadSnapshotEntry(line));
            } else {
                currentSnapshot.addEntry(new ThreadSnapshotEntry(line));
            }
        }
    }
    return threadSnapshots;
}
